func commentCursor(orderCol string, d *example.Comment) (string, error) {
	pk := strconv.FormatInt(d.ID, 10)
	if orderCol == "id" {
		return apiquery.EncodeCursor(pk), nil
	}
	k, ok := commentKey(orderCol, d)
	if !ok {
		return "", invalid("cannot order by " + orderCol)
	}
	return apiquery.EncodeCursor(k, pk), nil
}

// ListComments returns one page of Comment rows. It selects the relations the
// request asks for with one extra statement each, however many rows the page
// has.
func ListComments(ctx context.Context, q momo.Querier, first *int, after *string, filter *CommentFilter, order *CommentOrder) (*CommentConnection, error) {
	limit := 0
	if first != nil {
		limit = *first
	}
	limit = apiquery.ClampLimit(limit)
	orderCol, desc := "id", false
	if order != nil {
		var err error
		if orderCol, desc, err = parseOrder(commentOrderColumns, order.Field, order.Direction); err != nil {
			return nil, err
		}
	}
	if _, ok := commentKey(orderCol, &example.Comment{}); !ok && orderCol != "id" {
		return nil, invalid("cannot order by " + orderCol)
	}
	ref, err := commentdesc.ColumnByName(orderCol)
	if err != nil {
		return nil, err
	}
	items := []momo.Orderable{momo.Asc(ref)}
	if desc {
		items = []momo.Orderable{momo.Desc(ref)}
	}
	if orderCol != "id" {
		items = append(items, commentdesc.ID.Asc())
	}
	sel := momo.Select[example.Comment](q).OrderBy(items...).Limit(int64(limit + 1))
	if filter != nil {
		p, err := filter.predicate(0)
		if err != nil {
			return nil, err
		}
		if p != nil {
			sel = sel.Where(p)
		}
	}
	if after != nil && *after != "" {
		c, err := apiquery.DecodeCursor(*after)
		if err != nil {
			return nil, err
		}
		cols := []string{orderCol, "id"}
		if orderCol == "id" {
			cols = cols[:1]
		}
		if len(c.Keys) != len(cols) {
			return nil, invalid("invalid page cursor")
		}
		vals := make([]any, len(cols))
		for i, k := range c.Keys {
			if vals[i], err = commentKeyValue(cols[i], k); err != nil {
				return nil, invalid("invalid page cursor")
			}
		}
		sel = sel.After(vals...)
	}
	rows, err := sel.All(ctx)
	if err != nil {
		return nil, err
	}
	conn := &CommentConnection{Edges: []*CommentEdge{}, PageInfo: &PageInfo{}}
	if len(rows) > limit {
		rows = rows[:limit]
		conn.PageInfo.HasNextPage = true
	}
	for i := range rows {
		cursor, err := commentCursor(orderCol, &rows[i])
		if err != nil {
			return nil, err
		}
		conn.Edges = append(conn.Edges, &CommentEdge{Node: &rows[i], Cursor: cursor})
		conn.PageInfo.EndCursor = &cursor
	}
	return conn, nil
}

// GetComment returns the Comment with the given id, or nil when there is none. It
// selects the relations the request asks for.
func GetComment(ctx context.Context, q momo.Querier, id int64) (*example.Comment, error) {
	sel := momo.Select[example.Comment](q).Where(commentdesc.ID.Eq(id))
	row, err := sel.One(ctx)
	if errors.Is(err, momo.ErrNotFound) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	return &row, nil
}

